def parse_nested_parens(paren_string: str) -> List[int]:
    result = []
    current_depth = 0
    max_depth = 0
    for ch in paren_string:
        if ch == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch == ')':
            current_depth -= 1
        elif ch == ' ':
            # End of a group, append max_depth and reset counters
            if max_depth > 0 or current_depth == 0:
                result.append(max_depth)
            max_depth = 0
            current_depth = 0
    # Append the last group's max_depth if any
    if max_depth > 0 or current_depth == 0:
        result.append(max_depth)
    return result

