def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Find number of places where arr[i] > arr[i+1]
    count_breaks = 0
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            count_breaks += 1
            if count_breaks > 1:
                return False
    # Also check the boundary between last and first element (due to rotation)
    if arr[-1] > arr[0]:
        # If there is already a break inside array and the last element > first element,
        # then after rotation array won't be sorted
        if count_breaks == 1:
            return False
        # If no breaks inside but last > first, still not sorted after rotation
        if count_breaks == 0:
            return False
    # If zero or one break, it's possible to rotate to sorted array
    return True

