def max_fill(grid, capacity):
    # Each row is a well, each '1' is a unit of water.
    # We can remove up to 'capacity' units per well.
    # So for each row, count the number of 1s, then the removed water is min(count, capacity).
    # Sum these values for all wells.
    return sum(min(row.count(1), capacity) for row in grid)

