    def sort_word(word):
        return ''.join(sorted(word))

    # Split string into words and spaces, preserving spaces
    parts = re.split(r'(\s+)', s)

    # For each word (non-space part), sort its characters; spaces remain as is
    result_parts = [sort_word(part) if not part.isspace() else part for part in parts]

    return ''.join(result_parts)

