def maximum(arr, k):
    """
    Given an array arr of integers and a positive integer k, return a sorted list 
    of length k with the k largest elements from arr. If arr has fewer than k elements,
    the returned list should contain all elements of arr sorted, followed by enough
    copies of the maximum element in arr (or 0 if arr is empty) to make length k.
    """
    if not arr:
        # arr empty: return k zeros
        return [0]*k
    arr_sorted = sorted(arr, reverse=True)
    if len(arr_sorted) >= k:
        return sorted(arr_sorted[:k])
    else:
        max_val = arr_sorted[0]
        result = arr_sorted[:]  # copy all elements
        result.extend([max_val] * (k - len(arr_sorted)))
        return sorted(result)

