def triples_sum_to_zero(l, n=None):
    if n is None:
        n = len(l)
    if n < 3:
        return False

    # Condition: the three elements are odd
    # We look for three odd elements that sum to 0.
    # Approach: pick all odd elements, then check all triples.

    odds = [x for x in l if x % 2 != 0]
    length = len(odds)
    if length < 3:
        return False

    # Check all triples of odd elements for sum zero
    for i in range(length - 2):
