            for k in range(j + 1, length):
                if odds[i] + odds[j] + odds[k] == 0:
                    return True
    return False

def monotonic(arr, n=None):
    length = n if n is not None else len(arr)
    if length <= 1:
        return True
    non_decreasing = True
    non_increasing = True
    for i in range(1, length):
        if arr[i] < arr[i - 1]:
            non_decreasing = False
        if arr[i] > arr[i - 1]:
